counts = {}
with open("app.log", encoding="utf-8") as f:
    for line in f:
        parts = line.strip().split(" ", 4)
        if len(parts) < 5:
            continue
        level = parts[2]
        counts[level] = counts.get(level, 0) + 1
for level in sorted(counts):
    print(level + ": " + str(counts[level]))

fails = {}
with open("app.log", encoding="utf-8") as f:
    for line in f:
        parts = line.strip().split(" ", 4)
        if len(parts) < 5:
            continue
        if parts[4].startswith("LOGIN failed"):
            ip = parts[3]
            fails[ip] = fails.get(ip, 0) + 1
for ip in sorted(fails, key=lambda k: (-fails[k], k)):
    print(ip + ": " + str(fails[ip]))

fails = {}
with open("app.log", encoding="utf-8") as f:
    for line in f:
        parts = line.strip().split(" ", 4)
        if len(parts) < 5:
            continue
        if parts[4].startswith("LOGIN failed"):
            fails[parts[3]] = fails.get(parts[3], 0) + 1
bad = sorted(ip for ip in fails if fails[ip] >= 3)
if bad:
    for ip in bad:
        print("ALERT " + ip)
else:
    print("clean")
